  // Make sure dims does not contain a zero
  for (int i = 0; i < dims.size(); i++) {
    OP_REQUIRES(
        ctx, dims(i) != 0,
        errors::InvalidArgument("Input dims cannot contain a dim of zero, "
                                "but dims contains zero at index ",
                                i));
